    r->next = local->full_pools[sz];
    local->full_pools[sz] = r;
  }

  CAMLassert(
    /* either there's no more free space and we've moved the pool */
    (r->next_obj == 0 && local->full_pools[sz] == r)
    /* or there's still free space */
    || POOL_BLOCK_FREE_HP(r->next_obj));

